import {Injectable} from '@angular/core';
import {BaseService} from "../../../../../../base/services/base.service";
import {AuthService} from "../../../../../common/modules/auth/services/auth.service";
import {NotifierService} from "../../../../../../services/notifier/notifier.service";
import {HttpClient, HttpErrorResponse} from "@angular/common/http";
import {EventBusService} from "../../../../../../services/eventbus/event-bus.service";
import {IParams} from "../../../../../../base/endpoints/iparams";
import {DashEndpoint} from "../../../../dash.endpoint";
import {IPage, ResponseData} from "../../../../../../base/models/IPage";
import {IAuth} from "../../../../../common/modules/auth/models/auth.model";
import {IPostCategory, IPostCategoryDetail, IPostCategoryReq} from "../models/postcategory.model";
import {TopHashtag} from "../../../../../blog/models/top-hashtag.model";

@Injectable({
  providedIn: 'root'
})
export class PostCategoryService extends BaseService {

  constructor(
    authService: AuthService,
    notifier: NotifierService,
    private http: HttpClient,
    private eventBusService: EventBusService
  ) {
    super(authService, notifier)
  }

  search(key: string, endpoint: string, params: IParams) {
    let url = DashEndpoint.POST_CATEGORIES.SEARCH(endpoint, params)
    this.http.get<ResponseData<IPage<IPostCategory>>>(url)
      .subscribe((data: ResponseData<IPage<IPostCategory>>) => {
        this.eventBusService.publish(key, data.body)
      }, error => {
        this.handleError(error, (auth: IAuth) => {
          this.search(key, endpoint, params)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  getTopHashtags(key: string, blogSlug: string) {
    let url = DashEndpoint.BLOGPOSTS.GET_TOP_HASHTAGS(blogSlug)
    this.http.get<TopHashtag[]>(url)
      .subscribe((data: TopHashtag[]) => {
        this.eventBusService.publish(key, data)
      }, error => {
        this.handleError(error, (auth: IAuth) => {
          this.getTopHashtags(key, blogSlug)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  fetchSingle(key: string, endpoint: string, id: number) {
    this.http.get<ResponseData<IPostCategory>>(DashEndpoint.POST_CATEGORIES.GET(endpoint, id))
      .subscribe((data: ResponseData<IPostCategory>) => {
        this.eventBusService.publish(key, data.body)
      }, (error: HttpErrorResponse) => {
        this.handleError(error, (auth: IAuth) => {
          this.fetchSingle(key, endpoint, id)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  upsert(key: string, endpoint: string, postCategoryReq: IPostCategoryReq, exId: number | null) {
    let url = exId == null ? DashEndpoint.POST_CATEGORIES.CREATE(endpoint)
      : DashEndpoint.POST_CATEGORIES.UPDATE(endpoint, exId)

    let observable = exId == null ?
      this.http.post<ResponseData<IPostCategoryDetail>>(url, postCategoryReq)
      : this.http.patch<ResponseData<IPostCategoryDetail>>(url, postCategoryReq)

    observable.subscribe(res => {
      this.eventBusService.publish(key, res.body)
    }, (err: HttpErrorResponse) => {
      this.handleError(err, (auth: IAuth) => {
        this.upsert(key, endpoint, postCategoryReq, exId)
      }, (err: HttpErrorResponse) => {
        this.eventBusService.publish(this.getErrorKey(key), err)
      })
    })

  }


}
