import {Component, Inject} from '@angular/core';
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {defaultPostCategoryConfig, PostCategoryConfig, selfEndpoints, selfRoutes} from "../../models/config.model";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {PostCategoryService} from "../../services/postcategory.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {IImageSlice} from "../../../../../../common/modules/cms/files/models/file.model";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {IPostCategory, IPostCategoryDetail, IPostCategoryReq} from "../../models/postcategory.model";
import {IBlog} from "../../../blogs/models/blog.model";

@Component({
  selector: 'app-postcategory-upsert',
  templateUrl: './postcategory-upsert.component.html',
  styleUrls: ['./postcategory-upsert.component.scss']
})
export class PostCategoryUpsertComponent extends BaseUpsertComponentV3<IPostCategoryDetail> {

  config: PostCategoryConfig = defaultPostCategoryConfig

  selectedParent: IPostCategory | null = null
  selectedBlog: IBlog | null = null

  postCategoryForm = new FormGroup({
    name: new FormControl('', [Validators.required, Validators.minLength(3)]),
    description: new FormControl('', []),
    image: new FormControl<string | null>(null),
    parent_id: new FormControl<number | null>(null),
    blog_id: new FormControl<number | null>(null, [Validators.required])
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private postCategoryService: PostCategoryService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.title != null) {
      this.postCategoryForm.controls.name.setValue(dialogData.title)
    }

  }

  protected override componentName(): string {
    return PostCategoryUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: "PostCategorys",
        link: "/dash/postcategorys",
        active: false
      },
      {
        text: this.translations["Upsert"],
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.POST_CATEGORIES.GET(exId))
    this.postCategoryService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.postCategoryForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  onImgUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.postCategoryForm.controls.image.setValue(images[0].image_url)
    }
  }

  getExImages(): IImageSlice[] {
    let image = this.postCategoryForm.controls.image.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.POST_CATEGORIES.UPSERT(exId))
    let req = this.postCategoryForm.value as IPostCategoryReq
    this.postCategoryService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "PostCategory has been " + (exId ? "updated" : "created"))
      this.postCategoryForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.message)
    })
  }

  private populateForm(n: IPostCategoryDetail) {
    this.selectedParent = n.parent
    this.selectedBlog = n.blog

    this.postCategoryForm.controls.name.setValue(n.name)
    this.postCategoryForm.controls.description.setValue(n.description)
    this.postCategoryForm.controls.image.setValue(n.image == null ? null : n.image)
    this.postCategoryForm.controls.parent_id.setValue(n.parent?.id ?? null)
    this.postCategoryForm.controls.blog_id.setValue(n.blog.id)
  }

  onPostCategorySelected(category: IPostCategory | null) {
    this.selectedParent = category
    this.postCategoryForm.controls.parent_id.setValue(category?.id ?? null)
  }

  onBlogSelected(blog: IBlog | null) {
    this.selectedBlog = blog
    this.postCategoryForm.controls.blog_id.setValue(blog?.id ?? null)
  }
}
