import {Injectable} from '@angular/core';
import {BaseService} from "../../../../../../base/services/base.service";
import {AuthService} from "../../../../../common/modules/auth/services/auth.service";
import {NotifierService} from "../../../../../../services/notifier/notifier.service";
import {HttpClient, HttpErrorResponse} from "@angular/common/http";
import {EventBusService} from "../../../../../../services/eventbus/event-bus.service";
import {IParams} from "../../../../../../base/endpoints/iparams";
import {DashEndpoint} from "../../../../dash.endpoint";
import {IPage, ResponseData} from "../../../../../../base/models/IPage";
import {IAuth} from "../../../../../common/modules/auth/models/auth.model";
import {IBlogPost, IBlogPostDetail, IBlogPostReq} from "../models/blogpost.model";

@Injectable({
  providedIn: 'root'
})
export class BlogPostService extends BaseService {

  constructor(
    authService: AuthService,
    notifier: NotifierService,
    private http: HttpClient,
    private eventBusService: EventBusService
  ) {
    super(authService, notifier)
  }

  search(key: string, endpoint: string, params: IParams) {
    let url = DashEndpoint.BLOGPOSTS.SEARCH(endpoint, params)
    this.http.get<ResponseData<IPage<IBlogPost>>>(url)
      .subscribe((data: ResponseData<IPage<IBlogPost>>) => {
        this.eventBusService.publish(key, data.body)
      }, error => {
        this.handleError(error, (auth: IAuth) => {
          this.search(key, endpoint, params)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  fetchSingle(key: string, endpoint: string, id: number) {
    this.http.get<ResponseData<IBlogPost>>(DashEndpoint.BLOGPOSTS.GET(endpoint, id))
      .subscribe((data: ResponseData<IBlogPost>) => {
        this.eventBusService.publish(key, data.body)
      }, (error: HttpErrorResponse) => {
        this.handleError(error, (auth: IAuth) => {
          this.fetchSingle(key, endpoint, id)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  fetchSinglePublic(key: string, blogSlug: string, postSlug: string) {
    this.http.get<ResponseData<IBlogPost>>(DashEndpoint.BLOGPOSTS.GET_PUBLIC(DashEndpoint.BLOGPOSTS.BLOGPOST_ENDPOINT_PUBLIC, blogSlug, postSlug))
      .subscribe((data: ResponseData<IBlogPost>) => {
        this.eventBusService.publish(key, data.body)
      }, (error: HttpErrorResponse) => {
        this.handleError(error, (auth: IAuth) => {
          this.fetchSinglePublic(key, blogSlug, postSlug)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  upsert(key: string, endpoint: string, blogPostReq: IBlogPostReq, exId: number | null) {
    let url = exId == null ? DashEndpoint.BLOGPOSTS.CREATE(endpoint)
      : DashEndpoint.BLOGPOSTS.UPDATE(endpoint, exId)

    let observable = exId == null ?
      this.http.post<ResponseData<IBlogPostDetail>>(url, blogPostReq)
      : this.http.patch<ResponseData<IBlogPostDetail>>(url, blogPostReq)

    observable.subscribe(res => {
      this.eventBusService.publish(key, res.body)
    }, (err: HttpErrorResponse) => {
      this.handleError(err, (auth: IAuth) => {
        this.upsert(key, endpoint, blogPostReq, exId)
      }, (err: HttpErrorResponse) => {
        this.eventBusService.publish(this.getErrorKey(key), err)
      })
    })
  }

  publish(key: string, endpoint: string, blogpostId: number, publish: boolean) {
    let url = DashEndpoint.BLOGPOSTS.PUBLISH(endpoint, blogpostId, {published: publish})

    this.http.patch<ResponseData<IBlogPostDetail>>(url, null)
      .subscribe(res => {
        this.eventBusService.publish(key, res.body)
      }, (err: HttpErrorResponse) => {
        this.handleError(err, (auth: IAuth) => {
          this.publish(key, endpoint, blogpostId, publish)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

}
