import {Component, Inject, ViewChild} from '@angular/core';
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {BlogPostConfig, defaultBlogPostConfig, selfEndpoints, selfRoutes} from "../../models/config.model";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {BlogPostService} from "../../services/blogpost.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {IImageSlice} from "../../../../../../common/modules/cms/files/models/file.model";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {IBlogPostDetail, IBlogPostReq} from "../../models/blogpost.model";
import {IBlog} from "../../../blogs/models/blog.model";
import {IPostCategory} from "../../../postcategories/models/postcategory.model";
import {TextUtility} from "../../../../../../common/modules/utility/text.utility";
import {
  PostCategorySelectComponent
} from "../../../postcategories/components/postcategory-select/postcategory-select.component";

@Component({
  selector: 'app-blogpost-upsert',
  templateUrl: './blogpost-upsert.component.html',
  styleUrls: ['./blogpost-upsert.component.scss']
})
export class BlogPostUpsertComponent extends BaseUpsertComponentV3<IBlogPostDetail> {
  @ViewChild("categorySelect") categorySelect: PostCategorySelectComponent

  config: BlogPostConfig = defaultBlogPostConfig

  selectedBlog: IBlog | null = null
  selectedCategories: IPostCategory[] = []

  blogPostForm = new FormGroup({
    title: new FormControl('', [Validators.required, Validators.minLength(3), Validators.maxLength(255)]),
    slug: new FormControl('', [Validators.required, Validators.minLength(3), Validators.maxLength(255)]),
    featured_image: new FormControl<string | null>(null),
    blog_id: new FormControl<number | null>(null, [Validators.required]),
    hashtags: new FormControl<string[]>([]),
    label_ids: new FormControl<number[]>([]),
    category_ids: new FormControl<number[]>([]),
    content: new FormGroup({
      content: new FormControl<string>("", [Validators.minLength(10)])
    })
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private blogPostService: BlogPostService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.title != null) {
      this.blogPostForm.controls.title.setValue(dialogData.title)
    }

  }

  override ngOnInit() {
    super.ngOnInit();
    /*
      - Update slug when title is changed
      - Only during create, not during update as slug should be kept same as it'll be used in url
       */
    if (this.exId === null) {
      this.blogPostForm.controls.title.valueChanges.subscribe(value => {
        if (value == null) return
        this.blogPostForm.controls.slug.setValue(TextUtility.slugify(value))
      })
    }

  }

  protected override componentName(): string {
    return BlogPostUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: "BlogPosts",
        link: "/dash/blogposts",
        active: false
      },
      {
        text: this.translations["Upsert"],
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.BLOGPOSTS.GET(exId))
    this.blogPostService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.blogPostForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  onImgUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.blogPostForm.controls.featured_image.setValue(images[0].image_url)
    }
  }

  getExImages(): IImageSlice[] {
    let image = this.blogPostForm.controls.featured_image.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.BLOGPOSTS.UPSERT(exId))
    let req = this.blogPostForm.value as IBlogPostReq
    req.hashtags = TextUtility.extractHashtagsWithoutSymbols(req.content.content)
    console.log("hashtags", req.hashtags)
    this.blogPostService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "BlogPost has been " + (exId ? "updated" : "created"))
      this.blogPostForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.error.message)
    })
  }

  private populateForm(n: IBlogPostDetail) {
    this.selectedBlog = n.blog
    this.selectedCategories = n.categories

    this.blogPostForm.controls.title.setValue(n.title)
    this.blogPostForm.controls.slug.setValue(n.slug)
    this.blogPostForm.controls.featured_image.setValue(n.featured_image)
    this.blogPostForm.controls.blog_id.setValue(n.blog.id)
    this.blogPostForm.controls.content.setValue({
      content: n.content.content
    })
    this.blogPostForm.controls.label_ids.setValue(n.labels.map((l) => {
      return l.id
    }))
    this.blogPostForm.controls.hashtags.setValue(n.content.hashtags)
    this.blogPostForm.controls.category_ids.setValue(n.categories.map((c) => {
      return c.id
    }))
  }

  onCategorySelected(category: IPostCategory | null) {
    // if category is null or already selected, return
    if (category == null || this.selectedCategories.find(c => c.id == category.id)) {
      return
    }
    this.selectedCategories.push(category)
    this.blogPostForm.controls.category_ids.setValue(
      this.selectedCategories.map(c => c.id)
    )
  }

  removeCategory(category: IPostCategory) {
    this.selectedCategories = this.selectedCategories.filter(c => c.id != category.id)
    this.blogPostForm.controls.category_ids.setValue(
      this.selectedCategories.map(c => c.id)
    )
  }

  onBlogSelected(blog: IBlog | null) {
    this.selectedBlog = blog
    this.blogPostForm.controls.blog_id.setValue(blog?.id ?? null)
    this.selectedCategories = []
    this.categorySelect.clear()
    this.categorySelect.search({page: 0, size: 10, blog_id: blog?.id})
  }
}
