import {Component, Inject} from '@angular/core';
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {BlogConfig, defaultBlogConfig, selfEndpoints, selfRoutes} from "../../models/config.model";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {BlogService} from "../../services/blog.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {IImageSlice} from "../../../../../../common/modules/cms/files/models/file.model";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {IBlogDetail, IBlogReq} from "../../models/blog.model";
import {IOrganization} from "../../../../mdm/organizations/models/organization.model";


@Component({
  selector: 'app-blog-upsert',
  templateUrl: './blog-upsert.component.html',
  styleUrls: ['./blog-upsert.component.scss']
})
export class BlogUpsertComponent extends BaseUpsertComponentV3<IBlogDetail> {

  config: BlogConfig = defaultBlogConfig

  selectedOrg: IOrganization | null = null

  blogForm = new FormGroup({
    title: new FormControl('', [Validators.required, Validators.minLength(3)]),
    subtitle: new FormControl('', [Validators.required, Validators.minLength(10)]),
    logo: new FormControl<string | null>(null),
    header_image: new FormControl<string | null>(null),
    org_id: new FormControl<number | null>(null, [Validators.required])
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private blogService: BlogService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.title != null) {
      this.blogForm.controls.title.setValue(dialogData.title)
    }

  }

  protected override componentName(): string {
    return BlogUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: "Blogs",
        link: "/dash/blogs",
        active: false
      },
      {
        text: this.translations["Upsert"],
        link: null,
        active: true
      }
    ]
  }

  onOrgSelected($event: IOrganization | null) {
    this.selectedOrg = $event
    this.blogForm.controls.org_id.setValue(
      this.selectedOrg == null ? -1 : this.selectedOrg.id
    )
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.BLOGS.GET(exId))
    this.blogService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.blogForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  onLogoUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.blogForm.controls.logo.setValue(images[0].image_url)
    }
  }

  onBannerUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.blogForm.controls.header_image.setValue(images[0].image_url)
    }
  }

  getExLogo(): IImageSlice[] {
    let image = this.blogForm.controls.logo.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getExBanner(): IImageSlice[] {
    let image = this.blogForm.controls.header_image.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.BLOGS.UPSERT(exId))
    let req = this.blogForm.value as IBlogReq
    this.blogService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "Blog has been " + (exId ? "updated" : "created"))
      this.blogForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.message)
    })
  }

  private populateForm(n: IBlogDetail) {
    this.selectedOrg = n.organization

    this.blogForm.controls.title.setValue(n.title)
    this.blogForm.controls.subtitle.setValue(n.subtitle)
    this.blogForm.controls.logo.setValue(n.logo == null ? null : n.logo)
    this.blogForm.controls.header_image.setValue(n.header_image == null ? null : n.header_image)
    this.blogForm.controls.org_id.setValue(n.organization.id)
  }

}
