import {DashEndpoint} from "../../../../dash.endpoint";
import {BaseConfigV2} from "../../../../../../base/models/baseConfig";
import {Layout} from "../../../../../common/modules/generic/breadcrumb/breadcrumb.model";

export let selfEndpoints = {
  endpoint: DashEndpoint.BLOGPOSTS.BLOGPOST_ENDPOINT,
  adminEndpoint: DashEndpoint.BLOGPOSTS.BLOGPOST_ENDPOINT_ADMIN,
}

export interface BlogPostConfig extends BaseConfigV2 {
}

export let defaultBlogPostConfig: BlogPostConfig = {
  defaultLayout: Layout.GRID,
  upsertOnDialog: false,
  showUserFilter: false,
  showDeleteButton: true,
  endpoint: selfEndpoints.endpoint,
  delEndpoint: selfEndpoints.endpoint
}

export let selfRoutes = {
  list: "/dash/blog/blogposts",
  create: "/dash/blog/blogposts/create",
  update(id: number | null) {
    return id == null ? this.create : "/dash/blog/blogposts/" + id + '/update'
  }
}
