import {Component, EventEmitter, Input, Output, ViewChild} from '@angular/core';
import {PostCategoryUpsertComponent} from "../postcategory-upsert/postcategory-upsert.component";
import {selfEndpoints} from "../../models/config.model";
import {BaseComponent} from "../../../../../../../base/components/base.component";
import {IPostCategory, IPostCategoryDetail} from "../../models/postcategory.model";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {PostCategoryService} from "../../services/postcategory.service";
import {DialogService} from "../../../../../../common/modules/utility/components/popup/dialog.service";
import {TextUtility} from "../../../../../../common/modules/utility/text.utility";
import {IParams} from "../../../../../../../base/endpoints/iparams";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {NgSelectComponent} from "@ng-select/ng-select";

@Component({
  selector: 'app-postcategory-select',
  templateUrl: './postcategory-select.component.html',
  styleUrls: ['./postcategory-select.component.scss']
})
export class PostCategorySelectComponent extends BaseComponent {
  @ViewChild("categorySelect") categorySelect: NgSelectComponent | null = null

  @Input() enableAdd: boolean = true

  @Input() searchEndpoint: string = selfEndpoints.endpoint

  items: IPostCategory[] = []
  @Input() selectedItem: IPostCategory | null = null
  @Output() selected: EventEmitter<IPostCategory | null> = new EventEmitter<IPostCategory | null>()

  protected override componentName(): string {
    return PostCategorySelectComponent.name;
  }

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              authService: AuthService,
              private postCategoryService: PostCategoryService,
              private popupService: DialogService<IPostCategoryDetail>) {
    super(eventBus, router, subContainer)

    if (authService.isAdmin()) {
      this.searchEndpoint = selfEndpoints.adminEndpoint
    }
  }

  override ngOnInit(): void {
    this.loading = false
    this.search({
      page: 0, size: 10, q: null
    })
  }

  clear(){
    this.categorySelect?.clearModel()
  }

  searchForEvent(event: any) {
    let query = TextUtility.removeSpecialCharacters(event.target?.value)
    if (query.length > 2) {
      this.search({
        page: 0, size: 10, q: query
      })
    }
  }

  onSelected(event: any) {
    if (event == null) {
      this.selected.emit(null)
    } else if (this.items.find(c => c.name == event.name)) {
      this.selected.emit(this.selectedItem)
    } else {
      let popup = this.popupService.open(
        PostCategoryUpsertComponent, {id: null, dialogUpsert: true, title: event.title}
      )
      popup.componentInstance.onCompleted.subscribe((postcategory: IPostCategory | null) => {
        this.selected.emit(postcategory)
      })
      popup.componentInstance.onCanceled.subscribe(() => {
        popup.close()
      })
    }
  }

  search(params: IParams) {
    this.loading = true
    let key = this.componentKey(EventKey.POST_CATEGORIES.SEARCH(params))
    this.postCategoryService.search(key, this.searchEndpoint, params)
    this.subscribe(key, null, (value, meta) => {
      this.items = meta.data.content
      this.loading = false
    })
  }
}
